inline const Domain* parameterDomain(std::string_view effect, std::string_view key) noexcept {
    for (const auto& domain : kDomains) if (domain.effect == effect && domain.key == key) return &domain;
    return nullptr;
}
inline bool validParameter(std::string_view effect, std::string_view key, float value) noexcept {
    if (!std::isfinite(value)) return false;
    for (const auto& domain : kDomains) {
        if (domain.effect != effect || domain.key != key) continue;
        for (std::size_t i = 0U; i < domain.count; ++i)
            if (value == kDomainOptions[domain.offset + i]) return true;
        if (domain.step == 0.0f || value < domain.minimum || value > domain.maximum) return false;
        // Float32 is the Native command payload. Compare with the correctly
        // rounded Float32 representation of a legal step, not a broad epsilon.
        const double step = domain.step < 1.0f ? 0.1 : static_cast<double>(domain.step);
        const double index = std::round((static_cast<double>(value) - domain.minimum) / step);
        return value == static_cast<float>(domain.minimum + index * step);
    }
    return false;
}
